{
  "formato": "guion_cinematografico",
  "titulo": "LA SENSACION DE CERTEZA",
  "logline": "Un montaje audiovisual disecciona cómo ciertos titulares fabrican inevitabilidad, siembran sospecha con semántica y convierten investigación en veredicto emocional, guiando al público a conclusiones antes de tiempo.",
  "personajes": [
    {
      "id": "VOZ",
      "nombre": "VOZ EN OFF",
      "descripcion": "Narrador/a analítico/a. No “dicta” conclusiones: desarma mecanismos."
    },
    {
      "id": "EDITORA",
      "nombre": "EDITORA",
      "descripcion": "Crea titulares. Habla con precisión fría. Su objetivo es la sensación de certeza."
    },
    {
      "id": "LECTOR",
      "nombre": "LECTOR/A",
      "descripcion": "Intermediario emocional. Reacciona a cada truco como si fuera evidencia."
    }
  ],
  "estructura": [
    {
      "acto": 1,
      "secuencia_inicial": "SECUENCIA 1",
      "objetivo": "Plantear el tema: certeza fabricada. Presentar el patrón como tablero inevitable."
    },
    {
      "acto": 2,
      "secuencia_inicial": "SECUENCIA 2",
      "objetivo": "Mostrar herramientas: polarización como inevitable, truco semántico con comillas, atajo de autoridad."
    },
    {
      "acto": 3,
      "secuencia_inicial": "SECUENCIA 3",
      "objetivo": "Desviar el foco: judicializar y personalizar el conflicto para apagar el debate de fondo."
    }
  ],
  "secuencias": [
    {
      "id": "SECUENCIA 1",
      "duracion_aprox": "02:30",
      "lugar": "REDACCION MODERNA / SALA OSCURA",
      "descripcion": "Pantallas de titulares parpadean como si fueran fichas de un tablero. Cada entrada aparece y se conecta con líneas rojas, como circuitos emocionales.",
      "guion": [
        {
          "tipo": "PLANO",
          "detalles": "Primer plano de un cursor sobre un formulario de titular. La palabra 'INEVITABLE' aparece escrita en una tipografía que imita notificaciones."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Hoy no vamos a discutir “quiénes son los malos”. Vamos a discutir cómo se fabrica la sensación de certeza."
        },
        {
          "tipo": "CORTE RAPIDO",
          "detalles": "Titulares con elementos visuales: flechas, conexiones, etiquetas. Vox–PP aparece como un emparejamiento mecánico."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Mira el patrón: primero aparece la polarización como si fuera un tablero inevitable."
        },
        {
          "tipo": "PLANO",
          "detalles": "Línea de montaje: un titular se convierte en un 'puente' gráfico. Pero el puente no muestra datos: solo emociones."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Conectar Vox–PP se vende como “penetración ideológica”… pero muchas veces el titular no enseña el mecanismo."
        },
        {
          "tipo": "PLANO",
          "detalles": "Aparece una barra de progreso titulada 'CONCLUSIÓN'. Se llena antes que 'Verificación'."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Solo empuja tu mirada hacia una asociación emocional: te piden que concluyas sin haber comprobado el puente causal."
        }
      ]
    },
    {
      "id": "SECUENCIA 2",
      "duracion_aprox": "03:45",
      "lugar": "LABORATORIO SEMANTICO / ESTUDIO DE EDICION",
      "descripcion": "Todo ocurre como si la lengua fuera un dispositivo. Las comillas flotan como anzuelos. La credencial se anima, pero la confirmación no llega nunca.",
      "guion": [
        {
          "tipo": "PLANO",
          "detalles": "Plano detalle: una categoría aparece en pantalla con comillas rodeándola. Las comillas vibran como si susurraran."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Luego llega el truco semántico."
        },
        {
          "tipo": "PLANO",
          "detalles": "Texto en pantalla: “independientes”. Las comillas se agrandan. Detrás, un fondo oscuro se abre como si fuera una sospecha."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "“Independientes”, pero con comillas. Es decir: no es una descripción; es una sospecha en formato tipográfico."
        },
        {
          "tipo": "PLANO",
          "detalles": "El cursor del editor coloca comillas como si fueran una etiqueta de prisión."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Las comillas siembran duda automática y convierten una categoría en acusación anticipada."
        },
        {
          "tipo": "CORTE",
          "detalles": "Aparece la sigla UCO como un sello brillante. Su brillo “tapa” el texto que debería seguir."
        },
        {
          "tipo": "EDITORA",
          "texto": "Si pongo UCO, suena a cierre."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Después aparece el fetiche de autoridad: la UCO."
        },
        {
          "tipo": "PLANO",
          "detalles": "Titular cambia: de 'estudia' a 'acredita'. La palabra 'acredita' suena como sentencia en un tribunal acústico."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "El lenguaje usa verbos como “acredita” como si eso fuese lo mismo que una sentencia."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Y aquí está el atajo: credencial ≠ confirmación."
        },
        {
          "tipo": "PLANO",
          "detalles": "En paralelo, dos líneas: 'Procedimiento' avanza lento; 'Interpretación emocional' avanza rápido."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Un paso del procedimiento puede estar lejos del cierre… pero el titular lo presenta como resolución emocional."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Autoridad para cerrar interpretación."
        }
      ]
    },
    {
      "id": "SECUENCIA 3",
      "duracion_aprox": "04:10",
      "lugar": "CALLE / AULA / PASILLOS INSTITUCIONALES",
      "descripcion": "El caos social se reordena en un guion que lo personaliza todo. El foco se mueve como una cámara que evita el plano general y se queda en el rostro.",
      "guion": [
        {
          "tipo": "PLANO GENERAL",
          "detalles": "Multitud en el exterior. Se oye un ruido de fondo: voces, pasos, sirenas lejanas."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "¿Y cuando toca hablar del disturbio?"
        },
        {
          "tipo": "TRAVELING",
          "detalles": "La cámara hace zoom hacia una figura, como si la institución necesitara reducir el mundo a un responsable cercano."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Se desplaza el foco. De lo social y lo institucional… a la “mala parentalidad”."
        },
        {
          "tipo": "PLANO",
          "detalles": "Aparecen términos en pantalla como recortes: corrección disciplinaria, riña, conducta."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "A la corrección disciplinaria, a la riña."
        },
        {
          "tipo": "PLANO",
          "detalles": "Un titular cae sobre la imagen como una cortina: 'Judicializado'."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Judicializar se usa como cortina: si todo queda reducido a culpa individual o trámite judicial…"
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "…se apaga el debate de fondo."
        },
        {
          "tipo": "CORTE A NEGRO",
          "detalles": "Silencio breve. En pantalla: 'Limitaciones / Coste / Verificación' en tres columnas. Solo una columna aparece rellenándose."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "La conclusión es incómoda:"
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "No es que no haya información relevante."
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Es que el relato se empaqueta para orientar conclusiones antes de que el procedimiento termine…"
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "…y antes de que el lector reciba límites, coste y verificación comple—"
        },
        {
          "tipo": "PLANO FINAL",
          "detalles": "La palabra 'comple' se queda a medio escribir. Un gesto del editor borra y reescribe con un titular listo para compartir."
        },
        {
          "tipo": "LECTOR/A (susurro)",
          "texto": "Entonces… ya está, ¿no?"
        },
        {
          "tipo": "VOZ EN OFF",
          "texto": "Esa es la trampa: confundir velocidad con certeza."
        }
      ]
    }
  ],
  "recursos_visual_auditivos": {
    "estilo": "Montaje con tipografía activa, cortinas de texto, señales tipo HUD, y cortes que sincronizan emoción con titular.",
    "motivos": [
      "Comillas como anzuelos visuales",
      "Sello de autoridad como brillo que tapa el resto del proceso",
      "Barra de progreso emocional por delante de la verificación",
      "Cámara que evita planos generales y se queda en rostros culpabilizados"
    ],
    "musica_sonido": {
      "inicio": "Pulso electrónico seco con chasquidos de edición",
      "transicion": "Aumenta la percusión cuando aparecen siglas y verbos tipo 'acredita'",
      "final": "Silencio breve + zumbido de pantalla social al terminar el texto a medias"
    }
  },
  "nota_de_direccion": "El guion debe sentirse como un desmontaje: cada vez que el texto sugiere un mecanismo (polarización, comillas, autoridad, judicialización), la imagen debe mostrar un 'atajo' visual que completa una emoción antes que un hecho.",
  "cierre": {
    "forma": "Créditos con texto crítico animado",
    "texto_creditos": "La certeza no es un resultado: es una construcción. Y también puede desmontarse."
  }
}
